<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

class RekapHarianPanenSeeder extends Seeder
{
    public function run(): void
    {
        DB::table('rekap_harian_panen')->truncate();
        DB::table('rekap_bulanan_panen')->truncate();
        DB::table('rekap_tahunan_panen')->truncate();

        $validKecamatanIds = DB::table('kecamatan')->pluck('id')->toArray();

        $allData = $this->getData();

        $filtered = array_filter($allData, function($row) use ($validKecamatanIds) {
            return in_array($row['kecamatan_id'], $validKecamatanIds);
        });

        $filtered = array_map(function($row) {
            if (!isset($row['total_ltp'])) {
                $row['total_ltp'] = ($row['total_panen'] ?? 0) + ($row['oplah'] ?? 0) + ($row['gogo'] ?? 0);
            }
            return $row;
        }, $filtered);

        $chunks = array_chunk(array_values($filtered), 200);
        foreach ($chunks as $chunk) {
            DB::table('rekap_harian_panen')->insert($chunk);
        }

        $this->command->info('✅ RekapHarianPanenSeeder: ' . count($filtered) . ' records inserted.');
        $this->command->info('🔄 Sinkronisasi rekap bulanan dan tahunan panen...');

        $groups = DB::table('rekap_harian_panen')
            ->selectRaw('kabupaten_id, YEAR(tanggal) as tahun')
            ->distinct()
            ->get();

        foreach ($groups as $group) {
            \App\Models\RekapHarianPanen::updateRekapBulananFor($group->kabupaten_id, $group->tahun);
        }

        $this->command->info('✅ Sinkronisasi rekap bulanan & tahunan panen selesai.');
    }

